    out={}
    def add(b):
        r0,c0,r1,c1=b
        if r1-r0>=1 and c1-c0>=1:
            out[b]=None
    # TL
    for r in range(H):
        for c in range(W):
            if not mask[r,c]:
                continue
            if (r>0 and mask[r-1,c]) or (c>0 and mask[r,c-1]):
                continue
            c1=c
            while c1+1<W and mask[r,c1+1] and (r==0 or not mask[r-1,c1+1]):
                c1+=1
            r1=r
            while r1+1<H and mask[r1+1,c] and (c==0 or not mask[r1+1,c-1]):
                r1+=1
            add((r,c,r1,c1))
            # TR
            c0=c
    # TR
    for r in range(H):
        for c in range(W):
            if not mask[r,c]:
                continue
            if (r>0 and mask[r-1,c]) or (c+1<W and mask[r,c+1]):
                continue
            c0=c
            while c0-1>=0 and mask[r,c0-1] and (r==0 or not mask[r-1,c0-1]):
                c0-=1
            r1=r
            while r1+1<H and mask[r1+1,c] and (c==W-1 or not mask[r1+1,c+1]):
                r1+=1
            add((r,c0,r1,c))
    # BL
    for r in range(H):
        for c in range(W):
            if not mask[r,c]:
                continue
            if (r+1<H and mask[r+1,c]) or (c>0 and mask[r,c-1]):
                continue
            c1=c
            while c1+1<W and mask[r,c1+1] and (r==H-1 or not mask[r+1,c1+1]):
                c1+=1
            r0=r
            while r0-1>=0 and mask[r0-1,c] and (c==0 or not mask[r0-1,c-1]):
                r0-=1
            add((r0,c,r,c1))
    # BR
    for r in range(H):
        for c in range(W):
            if not mask[r,c]:
                continue
            if (r+1<H and mask[r+1,c]) or (c+1<W and mask[r,c+1]):
                continue
            c0=c
            while c0-1>=0 and mask[r,c0-1] and (r==H-1 or not mask[r+1,c0-1]):
                c0-=1
            r0=r
            while r0-1>=0 and mask[r0-1,c] and (c==W-1 or not mask[r0-1,c+1]):
                r0-=1
            add((r0,c0,r,c))
    return list(out)

def has_visible_pair(shape,b,above_masks):
    r0,c0,r1,c1=b
    vis=rect_mask(shape,b)
    if above_masks:
        union=np.zeros(shape,dtype=bool)
        for m in above_masks:
            union|=m
        vis &= ~union
    top = vis[r0,c0:c1+1].all()
    bottom = vis[r1,c0:c1+1].all()
    left = vis[r0:r1+1,c0].all()
    right = vis[r0:r1+1,c1].all()
    return (top and left) or (top and right) or (bottom and left) or (bottom and right)

def solve(mask,n):
    cands=enumerate_candidates(mask)
    shape=mask.shape
    sols=[]
    for combo in combinations(cands,n):
        union=np.zeros(shape,dtype=bool)
        for b in combo:
            union |= rect_mask(shape,b)
