        rectm=[rect_mask(shape,b) for b in combo]
        for perm in permutations(range(n)):
            top_to_bottom=perm
            ok=True
            for idx,pos in enumerate(top_to_bottom):
                above=[rectm[top_to_bottom[j]] for j in range(idx)]
                if not has_visible_pair(shape, combo[pos], above):
                    ok=False; break
            if ok:
                sols.append((combo,top_to_bottom))
    return cands, sols

# quick hand test
rects=[(1,1,6,8),(3,5,9,11)]
shape=(12,14)
mask=np.zeros(shape,dtype=bool)
for b in rects: mask|=rect_mask(shape,b)
print(mask.astype(int))
print(enumerate_candidates(mask))
print('sols', len(solve(mask,2)[1]))
for s in solve(mask,2)[1][:5]: print(s)
